"""Offline interactive view of a verified saved scenario calculation."""
import json
from html import escape
from pathlib import Path
from . import core, decision_lab


def generate(project):
    state = core.load(project)
    decision_lab.verify(project, state)
    core.require(bool(state.get('decision_lab')), 'Commit a decision lab first')
    record = state['decision_lab']
    payload = json.dumps({'input': record['input'], 'result': record['result']}, ensure_ascii=False, allow_nan=False)
    payload = payload.replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    page = TEMPLATE.replace('__DATA__', payload).replace('__TITLE__', escape(record['input']['title']))
    page = page.replace('__REVISION__', str(state['revision'])).replace('__HASH__', record['sha256'])
    path = Path(project)/'exports'/'decision-lab.html'
    core.atomic_write(path, page.encode('utf-8'))
    return path


TEMPLATE = '''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">
<title>Лаборатория решений · __TITLE__</title><style>
:root{font:16px/1.6 "Segoe UI",system-ui,sans-serif;color:#123c33;background:#f4f3ec;--green:#175c4b;--lime:#d5ef85;--muted:#597168}*{box-sizing:border-box}body{margin:0}header{background:#102f2c;color:#fff;padding:38px max(22px,calc((100vw - 1160px)/2)) 50px}header a{color:#d5ef85}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;color:#a4c7b2}h1{font-size:clamp(32px,5.2vw,58px);line-height:1.08;letter-spacing:-.035em;margin:26px 0 20px;max-width:780px}header p{color:#c3d7c8;max-width:780px;font-size:17px}main{max-width:1204px;padding:30px 22px 44px;margin:auto}section{margin-bottom:34px}h2{font-size:27px;line-height:1.2;letter-spacing:-.02em;margin:10px 0 16px}h3{margin:6px 0 14px;font-size:19px}p{margin:8px 0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:#fff;border:1px solid #dce4d7;border-radius:16px;padding:24px;min-width:0}.card.dark{background:var(--green);color:white;border:0}.card.dark .muted{color:#cee0d2}.big{font-size:36px;font-weight:650;line-height:1.2;margin:10px 0}.dark .big{color:var(--lime)}.muted{color:var(--muted);font-size:13px}.kicker{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.1em}.notice{border-left:4px solid #bc7928;background:#f8e9d1;padding:16px 20px;border-radius:0 10px 10px 0;font-size:14px;line-height:1.5;margin:20px 0}.switches{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0}button,select{font:inherit;border:1px solid #c0d1c3;border-radius:9px;background:white;padding:10px 13px;color:#174c3d;cursor:pointer}button[aria-pressed="true"]{background:var(--green);color:white;border-color:var(--green)}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #b9c541;outline-offset:3px}.two{display:grid;grid-template-columns:1.15fr 1fr;gap:18px}.tablewrap{overflow:auto;margin:10px 0}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:13px 12px;border-bottom:1px solid #dce4d7}th{color:#557064;font-size:12px;font-weight:650}td.good{font-weight:700;color:#175c4b;background:#e9f1d7}td.blocked{color:#89563e;text-decoration:line-through}.witness{font-size:12px;line-height:1.4;color:#567269}.bar{height:6px;background:#e2e9df;border-radius:8px;margin-top:6px}.bar span{display:block;background:#609d7e;height:6px;border-radius:8px}.chip{background:#edf3e2;color:#19553d;border-radius:20px;padding:4px 9px;font-size:12px;display:inline-block}.check{margin-bottom:12px}.check .value{float:right;font-weight:700}.row{display:flex;justify-content:space-between;gap:16px}.row span{max-width:70%}details{margin-top:12px}summary{cursor:pointer;font-weight:600}ul{padding-left:20px}a{color:#17694b}.hash{font:11px/1.5 ui-monospace,Consolas,monospace;overflow-wrap:anywhere}footer{border-top:1px solid #cad6c7;padding-top:24px;color:#567269;font-size:12px}#branch{min-height:175px}.tag{color:#9abd61;font-size:12px}select{max-width:100%;width:100%}code{font-size:12px}#basis{overflow-wrap:anywhere}@media(max-width:760px){.grid,.two{grid-template-columns:1fr}header{padding:25px 22px 30px}.card{padding:19px}h2{font-size:24px}.big{font-size:31px}th,td{padding:10px 7px}.row{flex-wrap:wrap}}@media print{header{background:white;color:#123c33}header p{color:#123c33}.switches{display:none}.grid,.two{display:block}.card{break-inside:avoid;margin-bottom:12px}}
</style></head><body><header><div class="eyebrow">Стратег Фабрики продуктов / Decision lab / v0.3</div><h1>Что заставит нас<br>изменить решение?</h1><p>__TITLE__</p><a href="dashboard.html">← Стратегия и исходные основания</a></header><main>
<section><div class="notice"><b>Сценарный расчёт, не прогноз бизнеса.</b> Все значения — авторские допущения. Указанные источники объясняют постановку вопроса и не доказывают эти числа. Выбор в интерфейсе ничего не утверждает и не меняет проект.</div><div class="grid" id="summary"></div></section>
<section><div class="kicker">01 / Устойчивость выбора</div><h2>Проверим другой ход событий</h2><div class="switches" id="scenarios"></div><div class="two"><div class="card" id="branch" aria-live="polite"></div><div class="card"><h3>Цена ошибочного выбора</h3><p class="muted">Разница с лучшим допустимым вариантом в том же сценарии. Меньше — лучше. Это не ожидаемый финансовый убыток.</p><div id="ranking"></div></div></div></section>
<section><div class="kicker">02 / Следующее исследование</div><h2>Какая проверка оправдывает затраты?</h2><p id="research-caption"></p><div class="two"><div id="checks"></div><div class="card"><h3>Решение после наблюдения</h3><label for="outcome">Выберите предусмотренный исход проверки</label><select id="outcome"></select><div id="policy" aria-live="polite"></div><p class="muted">Это условная ветвь анализа. Перед реальным выбором агент должен проверить наблюдение, пересмотреть основания и получить решение владельца.</p></div></div></section>
<section><div class="kicker">03 / Прозрачные допущения</div><h2>Каждое число можно оспорить</h2><div class="card"><p id="metric"></p><div class="tablewrap" id="matrix"></div><details><summary>Почему заданы именно такие значения</summary><div id="basis"></div></details><details><summary>Границы модели и жёсткие ограничения</summary><div id="limits"></div></details></div></section>
<footer>Снимок ревизии __REVISION__. Перед использованием после новых данных: <code>python -m strategist lab show &lt;project&gt;</code>. Изменения источников снимают актуальность анализа.<p class="hash">SHA-256: __HASH__</p><p>Не используется случайная выборка, назначенная моделью вероятность или скрытый рейтинг. Расчёт ограничен перечисленными сценариями.</p></footer>
</main><script id="lab-data" type="application/json">__DATA__</script><script>
const {input:m,result:r}=JSON.parse(document.getElementById('lab-data').textContent);
const $=id=>document.getElementById(id), esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(v), unit=m.unit==='utility_points'?'баллов полезности':m.unit, names=ids=>ids.map(id=>m.options.find(o=>o.id===id).name).join(' / ');
$('summary').innerHTML=[['Устойчивый кандидат',names(r.robust.candidates),'Минимальная максимальная цена ошибки'],['Верхняя граница ошибки',fmt(r.robust.worst_regret)+' '+unit,'В пределах заданных сценариев'],['Бюджет исследования',fmt(m.research_budget)+' '+unit,'Прямые затраты и цена задержки']].map((v,i)=>'<div class="card '+(!i?'dark':'')+'"><div class="kicker">'+esc(v[0])+'</div><div class="big" style="font-size:'+(!i?'24':'36')+'px">'+esc(v[1])+'</div><p class="muted">'+esc(v[2])+'</p></div>').join('');
let active=null;
function renderScenario(id){active=id;document.querySelectorAll('#scenarios button').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.id||null)===id)));const s=m.scenarios.find(s=>s.id===id), result=s?r.scenario_choices.find(x=>x.scenario===id):r.robust;
$('branch').innerHTML='<span class="chip">'+(s?'Если это подтвердится':'Пока сценарий неизвестен')+'</span><h3 style="margin-top:18px">'+esc(names(result.candidates))+'</h3><p>'+esc(s?s.assumption:'Сравниваем варианты по худшей цене ошибки. Ничья остаётся видимой и требует содержательного выбора.')+'</p><p class="muted">'+esc(s?'Что может опровергнуть сценарий: '+s.falsifier:m.coverage_limits)+'</p>';
const rows=r.robust.ranking.map(x=>({...x,value:s?x.regrets[id]:x.worst_regret})).sort((a,b)=>a.value-b.value||a.option.localeCompare(b.option));const max=Math.max(...rows.map(x=>x.value),1);
$('ranking').innerHTML=rows.map(x=>'<div style="margin:16px 0"><div class="row"><span>'+esc(names([x.option]))+'</span><b>'+fmt(x.value)+'</b></div><div class="bar"><span style="width:'+Math.max(1,x.value/max*100)+'%"></span></div>'+(s?'':'<p class="witness">Худший сценарий: '+esc(x.witness_scenarios.map(id=>m.scenarios.find(s=>s.id===id).name).join(', '))+'</p>')+'</div>').join('');}
$('scenarios').innerHTML='<button data-id="">Все сценарии</button>'+m.scenarios.map(s=>'<button data-id="'+esc(s.id)+'">'+esc(s.name)+'</button>').join('');document.querySelectorAll('#scenarios button').forEach(b=>b.addEventListener('click',()=>renderScenario(b.dataset.id||null)));renderScenario(null);$('scenarios').firstChild.setAttribute('aria-pressed','true');
$('research-caption').textContent=r.stop_research?'Ни одна описанная проверка не снижает гарантированную границу ошибки с учётом расходов. Это не означает, что любое исследование бесполезно: можно пересмотреть метод, бюджет или сценарии.':'Кандидат следующей проверки: '+r.next_checks.map(id=>m.checks.find(c=>c.id===id).name).join(' / ')+'. Результат зависит от полноты возможных исходов.';
$('checks').innerHTML=r.checks.map(c=>{const original=m.checks.find(x=>x.id===c.id);return '<div class="card check"><span class="chip">'+(r.next_checks.includes(c.id)?'Кандидат':!c.within_budget?'За пределами бюджета':c.bound_reduction>0?'Есть снижение границы':'Нет снижения границы')+'</span><h3>'+esc(c.name)+'</h3><p class="muted">Затраты '+fmt(c.total_cost)+' + остаточная ошибка '+fmt(c.residual_regret)+' = '+fmt(c.total_bound)+' '+esc(unit)+'</p><details><summary>Метод и ограничения</summary><p>'+esc(original.method)+'</p><p>'+esc(original.cost_basis)+'</p><p>'+esc(original.duration)+'</p><p>'+esc(original.limitations)+'</p></details></div>'}).join('')||'<p>Проверки ещё не описаны.</p>';
const outcomes=r.checks.flatMap(c=>c.outcomes.map(o=>({check:c,outcome:o})));$('outcome').innerHTML=outcomes.map((x,i)=>'<option value="'+i+'">'+esc(x.check.name+' → '+x.outcome.label)+'</option>').join('');
function renderPolicy(){const x=outcomes[Number($('outcome').value)];if(!x){$('policy').textContent='Нет описанных исходов.';return;}const o=x.outcome;$('policy').innerHTML='<h3 style="margin-top:20px">'+esc(names(o.candidates))+'</h3><p>Остаточная граница ошибки: <b>'+fmt(o.worst_regret)+' '+esc(unit)+'</b></p><p class="muted">Совместимые сценарии: '+esc(o.scenarios.map(id=>m.scenarios.find(s=>s.id===id).name).join('; '))+'</p>';}$('outcome').addEventListener('change',renderPolicy);renderPolicy();
$('metric').textContent=m.metric_definition+' · Горизонт: '+m.horizon+' · Единица: '+unit+'. Больше — лучше.';
$('matrix').innerHTML='<table><thead><tr><th>Сценарий</th>'+m.options.map(o=>'<th>'+esc(o.name)+'</th>').join('')+'</tr></thead><tbody>'+m.scenarios.map(s=>'<tr><td>'+esc(s.name)+'</td>'+m.options.map(o=>'<td class="'+(o.violations.length?'blocked':r.scenario_choices.find(x=>x.scenario===s.id).candidates.includes(o.id)?'good':'')+'">'+fmt(s.payoffs[o.id])+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
$('basis').innerHTML=m.scenarios.map(s=>'<h3>'+esc(s.name)+'</h3><p>'+esc(s.assumption)+'</p><ul>'+m.options.map(o=>'<li><b>'+esc(o.name)+':</b> '+esc(s.payoff_rationale[o.id])+'</li>').join('')+'</ul><p class="muted">Связанные выводы: '+esc(s.claim_refs.join(', '))+'. Они не являются доказательством числовых допущений.</p>').join('');
$('limits').innerHTML='<p>'+esc(m.coverage_limits)+'</p><p>Жёсткие ограничения исключают варианты до расчёта; штрафные баллы их не компенсируют.</p>'+m.constraints.map(c=>'<p><b>'+esc(c.rule)+':</b> '+esc(c.basis)+'</p>').join('')+'<p>Исключены: '+esc(r.excluded_options.length?names(r.excluded_options):'нет')+'</p><p>Минимакс рассматривает худший исход, не его вероятность. Это консервативный способ сравнения, а не универсальная целевая функция руководителя.</p>';
</script></body></html>'''
